/** How far ahead the overdue job looks when collecting due issues. */
export const OVERDUE_LOOKAHEAD_HOURS: number = 24;

/** Open milestones one project may hold at once. Closed milestones do not count. */
export const MAX_OPEN_MILESTONES_PER_PROJECT: number = 10;

export type ProjectId = Branded<string, "ProjectId">;
export type MilestoneId = Branded<string, "MilestoneId">;
export type IssueId = Branded<string, "IssueId">;

import type {
  IsoTimestamp,
  MilestoneId,
  ProjectId,
  TenantScoped,
  Timestamps,
} from "./common";

export interface Milestone extends Timestamps, TenantScoped {
  readonly id: MilestoneId;
  readonly projectId: ProjectId;
  readonly name: string;
  readonly targetDate: IsoTimestamp | null;
  readonly closedAt: IsoTimestamp | null;
}

export interface MilestoneProgress {
  readonly total: number;
  readonly open: number;
  readonly closed: number;
}

export interface MilestoneWithProgress {
  readonly milestone: Milestone;
  readonly progress: MilestoneProgress;
  readonly overdue: boolean;
}

export * from "./project";
export * from "./milestone";
export * from "./issue";

readonly parentId: IssueId | null;
readonly milestoneId: MilestoneId | null;
readonly estimate: number | null;

"project.restored": EventEnvelope & { projectId: ProjectId };
"milestone.created": EventEnvelope & {
  milestoneId: MilestoneId;
  projectId: ProjectId;
};
"milestone.reopened": EventEnvelope & {
  milestoneId: MilestoneId;
  projectId: ProjectId;
};
"milestone.closed": EventEnvelope & {
  milestoneId: MilestoneId;
  projectId: ProjectId;
  movedToMilestoneId: MilestoneId | null;
  movedIssueIds: readonly IssueId[];
};
"issue.created": EventEnvelope & {

/**
 * Milestone domain rules that are not authorization or tenancy.
 *
 * Name identity ignores letter case and surrounding whitespace, and the open
 * milestone cap is enforced by the service with `MilestoneStateError`.
 */

/** Comparison key for milestone names within one project. */
export function milestoneNameKey(name: string): string {
  return name.trim().toLowerCase();
}

/**
 * A milestone operation that conflicts with the milestone's current state:
 * it is closed when an open one is required, already open, over the open
 * cap, or the name is already used in the project.
 */
export class MilestoneStateError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly reason: "closed" | "already_open" | "too_many_open" | "name_taken",
  ) {
    super(`Milestone state conflict: ${reason}`);
    this.name = "MilestoneStateError";
  }
}

