/** Comparison key for milestone names within one project. */
export function milestoneNameKey(name: string): string {
  return name.trim().toLowerCase();
}

/**
 * A milestone operation that conflicts with the milestone's current state:
 * it is closed when an open one is required, already open, over the open
 * cap, or the name is already used in the project.
