/**
 * Moves live, still-open issues off a milestone. Closed and archived issues
 * stay where they are. Returns the ids that moved.
 */
export async function moveOpenIssuesFromMilestone(
  orgId: OrgId,
  fromMilestoneId: MilestoneId,
  toMilestoneId: MilestoneId | null,
  at: IsoTimestamp,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .update(issues)
    .set({ milestoneId: toMilestoneId, updatedAt: at })
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.milestoneId, fromMilestoneId),
          livePredicate(issues.archivedAt, {}),
          notInArray(issues.status, [...CLOSED_ISSUE_STATUSES]),
        ),
      ),
    )
    .returning({ id: issues.id })
    .all();

  return rows.map((row) => row.id as IssueId);
}

/**
 * Live-issue counts for each milestone: total, still open, and closed
 * (done or canceled). Archived issues are left out.
 */
export async function progressForMilestones(
  orgId: OrgId,
  milestoneIds: readonly MilestoneId[],
): Promise<ReadonlyMap<string, MilestoneProgress>> {
  const totals = new Map<string, { total: number; open: number; closed: number }>();
  for (const id of milestoneIds) {
    totals.set(id, { total: 0, open: 0, closed: 0 });
  }
  if (milestoneIds.length === 0) return totals;

  const rows = getDb()
    .select({
      milestoneId: issues.milestoneId,
      status: issues.status,
      value: count(),
    })
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          inArray(issues.milestoneId, [...milestoneIds]),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .groupBy(issues.milestoneId, issues.status)
    .all();

  for (const row of rows) {
    if (row.milestoneId === null) continue;
    const bucket = totals.get(row.milestoneId) ?? {
      total: 0,
      open: 0,
      closed: 0,
    };
    bucket.total += row.value;
    if (CLOSED_ISSUE_STATUSES.includes(row.status)) {
      bucket.closed += row.value;
    } else {
      bucket.open += row.value;
    }
    totals.set(row.milestoneId, bucket);
  }

  return totals;
}

