/**
 * Milestone lifecycle: names, the open-milestone cap, close/reopen and progress.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, assertNotArchived
 */
import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { emit } from "@/lib/event-bus";
import { MilestoneStateError } from "@/lib/milestones";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as milestoneRepo from "@/server/repositories/milestone-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import {
  actorEnvelope,
  NotFoundError,
  projectResource,
  requireFound,
} from "./_support";
import type {
  CloseMilestoneInput,
  CreateMilestoneInput,
  UpdateMilestoneInput,
} from "@/schemas/milestone";
import type { IsoTimestamp, MilestoneId, OrgId, ProjectId } from "@/types/common";
import { toIsoTimestamp } from "@/types/common";
import type { Actor } from "@/types/member";
import type {
  Milestone,
  MilestoneProgress,
  MilestoneWithProgress,
} from "@/types/milestone";
import type { Project } from "@/types/project";

/**
 * Open milestones first, then closed. Within a group, earliest target date
 * first and undated milestones last; equal dates keep the older milestone.
 */
function compareMilestones(a: Milestone, b: Milestone): number {
  const groupA = a.closedAt === null ? 0 : 1;
  const groupB = b.closedAt === null ? 0 : 1;
  if (groupA !== groupB) return groupA - groupB;

  const dateA = targetMillis(a.targetDate);
  const dateB = targetMillis(b.targetDate);
  if (dateA === null && dateB !== null) return 1;
  if (dateA !== null && dateB === null) return -1;
  if (dateA !== null && dateB !== null && dateA !== dateB) return dateA - dateB;

  if (a.createdAt < b.createdAt) return -1;
  if (a.createdAt > b.createdAt) return 1;
  if (a.id < b.id) return -1;
  if (a.id > b.id) return 1;
  return 0;
}

function targetMillis(value: IsoTimestamp | null): number | null {
  if (value === null) return null;
  const ms = new Date(value).getTime();
  return Number.isNaN(ms) ? null : ms;
}

/**
 * Overdue only when the milestone is still open, a target date is strictly
 * in the past, and at least one live issue is still open.
 */
function isOverdue(
  milestone: Milestone,
  progress: MilestoneProgress,
  nowMs: number,
): boolean {
  if (milestone.closedAt !== null) return false;
  if (progress.open <= 0) return false;
  const due = targetMillis(milestone.targetDate);
  if (due === null) return false;
  return due < nowMs;
}

async function loadEditableProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project> {
  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);
  return project;
}

async function assertNameAvailable(
  orgId: OrgId,
  projectId: ProjectId,
  name: string,
  exceptId?: MilestoneId,
): Promise<void> {
  const taken = await milestoneRepo.findMilestoneByName(orgId, projectId, name);
  if (taken && taken.id !== exceptId) {
    throw new MilestoneStateError("name_taken");
  }
}

async function assertOpenCap(orgId: OrgId, projectId: ProjectId): Promise<void> {
  const open = await milestoneRepo.countOpenMilestones(orgId, projectId);
  if (open >= MAX_OPEN_MILESTONES_PER_PROJECT) {
    throw new MilestoneStateError("too_many_open");
  }
}

async function withProgress(
  orgId: OrgId,
  milestones: readonly Milestone[],
  nowMs: number,
): Promise<readonly MilestoneWithProgress[]> {
  const progress = await issueRepo.progressForMilestones(
    orgId,
    milestones.map((milestone) => milestone.id),
  );
  return milestones.map((milestone) => {
    const counts = progress.get(milestone.id) ?? { total: 0, open: 0, closed: 0 };
    return {
      milestone,
      progress: counts,
      overdue: isOverdue(milestone, counts, nowMs),
    };
  });
}

export async function createMilestone(
  actor: Actor,
  input: CreateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);
  await loadEditableProject(actor, input.orgId, input.projectId);
  await assertNameAvailable(input.orgId, input.projectId, input.name);
  await assertOpenCap(input.orgId, input.projectId);

  const milestone = await milestoneRepo.insertMilestone(input);

  await emit("milestone.created", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
  });

  return milestone;
}

export async function updateMilestone(
  actor: Actor,
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(input.orgId, input.milestoneId),
    "Milestone",
    input.milestoneId,
  );
  await loadEditableProject(actor, input.orgId, milestone.projectId);

  if (input.name !== undefined) {
    await assertNameAvailable(
      input.orgId,
      milestone.projectId,
      input.name,
      milestone.id,
    );
  }

  if (input.name === undefined && input.targetDate === undefined) {
    return milestone;
  }

  return milestoneRepo.updateMilestone(input);
}

/**
 * Closes an open milestone. Its open live issues move to `moveOpenIssuesTo`
 * when that is another open milestone of the same project, and otherwise
 * leave the milestone. Closed and archived issues stay.
 */
export async function closeMilestone(
  actor: Actor,
  input: CloseMilestoneInput,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);

  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(input.orgId, input.milestoneId),
    "Milestone",
    input.milestoneId,
  );
  await loadEditableProject(actor, input.orgId, milestone.projectId);

  if (milestone.closedAt !== null) {
    throw new MilestoneStateError("closed");
  }

  const moveTo = input.moveOpenIssuesTo ?? null;
  if (moveTo !== null) {
    if (moveTo === milestone.id) {
      throw new NotFoundError("Milestone", moveTo);
    }
    const target = await milestoneRepo.findMilestoneById(input.orgId, moveTo);
    if (target === null || target.projectId !== milestone.projectId) {
      throw new NotFoundError("Milestone", moveTo);
    }
    if (target.closedAt !== null) {
      throw new MilestoneStateError("closed");
    }
  }

  const now = toIsoTimestamp(new Date());
  const movedIssueIds = await issueRepo.moveOpenIssuesFromMilestone(
    input.orgId,
    milestone.id,
    moveTo,
    now,
  );
  const closed = await milestoneRepo.setMilestoneClosedAt(
    input.orgId,
    milestone.id,
    now,
  );

  await emit("milestone.closed", {
    ...actorEnvelope(actor),
    milestoneId: closed.id,
    projectId: closed.projectId,
    movedToMilestoneId: moveTo,
    movedIssueIds,
  });

  return { milestone: closed, movedIssueIds };
}

export async function reopenMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  assertOrgScope(actor, orgId);

  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  await loadEditableProject(actor, orgId, milestone.projectId);

  if (milestone.closedAt === null) {
    throw new MilestoneStateError("already_open");
  }

  await assertOpenCap(orgId, milestone.projectId);

  const reopened = await milestoneRepo.setMilestoneClosedAt(
    orgId,
    milestone.id,
    null,
  );

  await emit("milestone.reopened", {
    ...actorEnvelope(actor),
    milestoneId: reopened.id,
    projectId: reopened.projectId,
  });

  return reopened;
}

export async function listMilestones(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly MilestoneWithProgress[]> {
  assertOrgScope(actor, orgId);

  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:read", projectResource(project));

  const milestones = [
    ...(await milestoneRepo.listMilestones(orgId, projectId)),
  ].sort(compareMilestones);

  return withProgress(orgId, milestones, Date.now());
}

export async function getMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<MilestoneWithProgress> {
  assertOrgScope(actor, orgId);

  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  const project = requireFound(
    await projectRepo.findProjectById(orgId, milestone.projectId),
    "Project",
    milestone.projectId,
  );
  assertCan(actor, "project:read", projectResource(project));

  const [withCounts] = await withProgress(orgId, [milestone], Date.now());
  return withCounts!;
}

