  assertOrgScope(actor, input.orgId);

  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(input.orgId, input.milestoneId),
    "Milestone",
    input.milestoneId,
  );
  await loadEditableProject(actor, input.orgId, milestone.projectId);

  if (milestone.closedAt !== null) {
    throw new MilestoneStateError("closed");
  }

  const moveTo = input.moveOpenIssuesTo ?? null;
  if (moveTo !== null) {
    if (moveTo === milestone.id) {
      throw new NotFoundError("Milestone", moveTo);
    }
    const target = await milestoneRepo.findMilestoneById(input.orgId, moveTo);
    if (target === null || target.projectId !== milestone.projectId) {
      throw new NotFoundError("Milestone", moveTo);
    }
    if (target.closedAt !== null) {
      throw new MilestoneStateError("closed");
    }
  }

  const now = toIsoTimestamp(new Date());
  const movedIssueIds = await issueRepo.moveOpenIssuesFromMilestone(
    input.orgId,
    milestone.id,
    moveTo,
    now,
  );
  const closed = await milestoneRepo.setMilestoneClosedAt(
    input.orgId,
    milestone.id,
    now,
  );

  await emit("milestone.closed", {
    ...actorEnvelope(actor),
    milestoneId: closed.id,
    projectId: closed.projectId,
    movedToMilestoneId: moveTo,
    movedIssueIds,
  });

