/**
 * Open milestones first, then closed. Within a group, earliest target date
 * first and undated milestones last; equal dates keep the older milestone.
 */
function compareMilestones(a: Milestone, b: Milestone): number {
  const groupA = a.closedAt === null ? 0 : 1;
  const groupB = b.closedAt === null ? 0 : 1;
  if (groupA !== groupB) return groupA - groupB;

  const dateA = targetMillis(a.targetDate);
  const dateB = targetMillis(b.targetDate);
  if (dateA === null && dateB !== null) return 1;
  if (dateA !== null && dateB === null) return -1;
  if (dateA !== null && dateB !== null && dateA !== dateB) return dateA - dateB;

  if (a.createdAt < b.createdAt) return -1;
  if (a.createdAt > b.createdAt) return 1;
  if (a.id < b.id) return -1;
  if (a.id > b.id) return 1;
  return 0;
}

function targetMillis(value: IsoTimestamp | null): number | null {
  if (value === null) return null;
  const ms = new Date(value).getTime();
  return Number.isNaN(ms) ? null : ms;
}

/**
 * Overdue only when the milestone is still open, a target date is strictly
 * in the past, and at least one live issue is still open.
 */
function isOverdue(
  milestone: Milestone,
  progress: MilestoneProgress,
  nowMs: number,
): boolean {
  if (milestone.closedAt !== null) return false;
  if (progress.open <= 0) return false;
  const due = targetMillis(milestone.targetDate);
  if (due === null) return false;
  return due < nowMs;
}

