/**
 * Puts an issue in an open milestone of its own project, moves it, or clears
 * the milestone. An archived issue or project is refused, and a bad milestone
 * creates no change.
 */
export async function setIssueMilestone(
  actor: Actor,
  input: SetIssueMilestoneInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, issue.projectId),
    "Project",
    issue.projectId,
  );
  assertNotArchived("Project", project.id, project);

  if (input.milestoneId !== null) {
    const milestone = await milestoneRepo.findMilestoneById(
      input.orgId,
      input.milestoneId,
    );
    if (milestone === null || milestone.projectId !== issue.projectId) {
      throw new NotFoundError("Milestone", input.milestoneId);
    }
    if (milestone.closedAt !== null) {
      throw new MilestoneStateError("closed");
    }
  }

  return issueRepo.setIssueMilestone(
    input.orgId,
    input.issueId,
    input.milestoneId,
  );
}","tool_output_for_prompt":"The file /private/var/folders/82/dclbn8z5181_3ppfdtp8csd40000gn/T/bench-scratch/3fa42d6e-2c78-43fa-8106-26e03e8afe0d/src/server/services/issue-service.ts has been updated successfully.","tool_output_for_prompt_concise":"The file /private/var/folders/82/dclbn8z5181_3ppfdtp8csd40000gn/T/bench-scratch/3fa42d6e-2c78-43fa-8106-26e03e8afe0d/src/server/services/issue-service.ts has been updated.","absolute_path":"/private/var/folders/82/dclbn8z5181_3ppfdtp8csd40000gn/T/bench-scratch/3fa42d6e-2c78-43fa-8106-26e03e8afe0d/src/server/services/issue-service.ts","edits":{"details":[{"old_string":"  return issueRepo.listBoardColumns(orgId, projectId);
