import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { subscribe } from "@/lib/event-bus";
import { MilestoneStateError } from "@/lib/milestones";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import { NotFoundError } from "@/server/services/_support";
import { registerActivityListeners, listActivity } from "@/server/services/activity-service";
import * as issueService from "@/server/services/issue-service";
import * as milestoneService from "@/server/services/milestone-service";
import { listNotifications } from "@/server/services/notification-service";
import * as projectService from "@/server/services/project-service";
import { toIsoTimestamp } from "@/types/common";
import type { MilestoneId } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;
const detach = registerActivityListeners();

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("milestones", "growth");
});

afterAll(() => {
  detach();
  cleanup();
});

const PAST = toIsoTimestamp("2020-01-01T00:00:00.000Z");
const FUTURE = toIsoTimestamp("2099-01-01T00:00:00.000Z");

function wait(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

describe("milestones", () => {
  it("covers the milestone lifecycle", async () => {
    const actor = tenant.actors.member;
    const orgId = tenant.org.id;
    const projectId = tenant.project.id;

    const seenCreated: unknown[] = [];
    const offCreated = subscribe("milestone.created", (payload) => {
      seenCreated.push(payload);
    });

    const alpha = await milestoneService.createMilestone(actor, {
      orgId,
      projectId,
      name: "Sprint 1",
      targetDate: FUTURE,
    });
    expect(alpha.closedAt).toBeNull();
    expect(alpha.name).toBe("Sprint 1");
    expect(seenCreated).toHaveLength(1);

    await expect(
      milestoneService.createMilestone(actor, {
        orgId,
        projectId,
        name: "  sprint 1 ",
        targetDate: null,
      }),
    ).rejects.toMatchObject({ reason: "name_taken" });

    const renamed = await milestoneService.updateMilestone(actor, {
      orgId,
      milestoneId: alpha.id,
      name: "  Sprint 1  ",
    });
    expect(renamed.name).toBe("  Sprint 1  ");

    const dated = await milestoneService.updateMilestone(actor, {
      orgId,
      milestoneId: alpha.id,
      targetDate: PAST,
    });
    expect(dated.targetDate).toBe(PAST);

    await expect(
      milestoneService.createMilestone(tenant.actors.viewer, {
        orgId,
        projectId,
        name: "Nope",
        targetDate: null,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      milestoneService.createMilestone(actor, {
        orgId: tenant.org.id,
        projectId: "01HZZZPPPPPPPPPPPPPPPPPPPP" as typeof projectId,
        name: "Missing",
        targetDate: null,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const other = await createTenant("milestones-other", "growth");
    await expect(
      milestoneService.listMilestones(other.actors.owner, orgId, projectId),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      milestoneService.getMilestone(actor, orgId, "01HZZZMMMMMMMMMMMMMMMMMMMM" as MilestoneId),
    ).rejects.toBeInstanceOf(NotFoundError);

    const beta = await milestoneService.createMilestone(actor, {
      orgId,
      projectId,
      name: "Beta",
      targetDate: FUTURE,
    });
    await wait(5);
    const undated = await milestoneService.createMilestone(actor, {
      orgId,
      projectId,
      name: "Undated",
      targetDate: null,
    });

    const openIssue = await issueService.createIssue(
      actor,
      issueInput(orgId, projectId, {
        title: "Open work",
        assigneeId: tenant.userIds.admin,
      }),
    );
    const placed = await issueService.setIssueMilestone(actor, {
      orgId,
      issueId: openIssue.id,
      milestoneId: alpha.id,
    });
    expect(placed.milestoneId).toBe(alpha.id);

    const second = await issueService.createIssue(actor, {
      ...issueInput(orgId, projectId, {
        title: "Also open",
        assigneeId: tenant.userIds.admin,
      }),
      milestoneId: alpha.id,
    });
    expect(second.milestoneId).toBe(alpha.id);

    const mine = await issueService.createIssue(actor, {
      ...issueInput(orgId, projectId, {
        title: "Mine",
        assigneeId: tenant.userIds.member,
      }),
      milestoneId: alpha.id,
    });
    const loose = await issueService.createIssue(actor, {
      ...issueInput(orgId, projectId, { title: "Unassigned" }),
      milestoneId: alpha.id,
    });
    const done = await issueService.createIssue(actor, {
      ...issueInput(orgId, projectId, {
        title: "Finished",
        assigneeId: tenant.userIds.viewer,
      }),
      milestoneId: alpha.id,
    });
    await issueService.changeIssueStatus(actor, {
      orgId,
      issueId: done.id,
      status: "done",
    });
    const canceled = await issueService.createIssue(actor, {
      ...issueInput(orgId, projectId, { title: "Canceled" }),
      milestoneId: alpha.id,
    });
    await issueService.changeIssueStatus(actor, {
      orgId,
      issueId: canceled.id,
      status: "canceled",
    });
    const archived = await issueService.createIssue(actor, {
      ...issueInput(orgId, projectId, { title: "Archived open" }),
      milestoneId: alpha.id,
    });
    await issueService.archiveIssue(actor, orgId, archived.id);

    const progress = await milestoneService.getMilestone(actor, orgId, alpha.id);
    expect(progress.progress).toEqual({ total: 6, open: 4, closed: 2 });
    expect(progress.overdue).toBe(true);

    const futureView = await milestoneService.updateMilestone(actor, {
      orgId,
      milestoneId: alpha.id,
      targetDate: FUTURE,
    });
    expect(futureView.targetDate).toBe(FUTURE);
    expect(
      (await milestoneService.getMilestone(actor, orgId, alpha.id)).overdue,
    ).toBe(false);
    await milestoneService.updateMilestone(actor, {
      orgId,
      milestoneId: alpha.id,
      targetDate: PAST,
    });

    const cleared = await milestoneService.updateMilestone(actor, {
      orgId,
      milestoneId: undated.id,
      targetDate: null,
    });
    expect(cleared.targetDate).toBeNull();
    expect(
      (await milestoneService.getMilestone(actor, orgId, undated.id)).overdue,
    ).toBe(false);

    await expect(
      issueService.setIssueMilestone(actor, {
        orgId,
        issueId: openIssue.id,
        milestoneId: beta.id,
      }),
    ).resolves.toMatchObject({ milestoneId: beta.id });
    await issueService.setIssueMilestone(actor, {
      orgId,
      issueId: openIssue.id,
      milestoneId: alpha.id,
    });

    const closedBeta = await milestoneService.closeMilestone(actor, {
      orgId,
      milestoneId: beta.id,
      moveOpenIssuesTo: null,
    });
    expect(closedBeta.movedIssueIds).toEqual([]);

    await expect(
      issueService.setIssueMilestone(actor, {
        orgId,
        issueId: openIssue.id,
        milestoneId: beta.id,
      }),
    ).rejects.toBeInstanceOf(MilestoneStateError);

    await expect(
      issueService.createIssue(actor, {
        ...issueInput(orgId, projectId, { title: "Should not exist" }),
        milestoneId: beta.id,
      }),
    ).rejects.toBeInstanceOf(MilestoneStateError);
    const still = await issueRepo.listIssues({
      orgId,
      limit: 100,
      cursor: null,
      query: "Should not exist",
    });
    expect(still.total).toBe(0);

    const beforeClose = await issueRepo.findIssueById(orgId, openIssue.id);
    await expect(
      milestoneService.closeMilestone(actor, {
        orgId,
        milestoneId: alpha.id,
        moveOpenIssuesTo: alpha.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    expect((await issueRepo.findIssueById(orgId, openIssue.id))?.milestoneId).toBe(
      beforeClose?.milestoneId,
    );
    expect(
      (await milestoneService.getMilestone(actor, orgId, alpha.id)).milestone.closedAt,
    ).toBeNull();

    await expect(
      milestoneService.closeMilestone(actor, {
        orgId,
        milestoneId: alpha.id,
        moveOpenIssuesTo: beta.id,
      }),
    ).rejects.toMatchObject({ reason: "closed" });
    expect(
      (await milestoneService.getMilestone(actor, orgId, alpha.id)).milestone.closedAt,
    ).toBeNull();

    const otherProject = await projectService.createProject(tenant.actors.admin, {
      orgId,
      name: "Side project",
      slug: "side",
      key: "SIDE",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    const foreign = await milestoneService.createMilestone(actor, {
      orgId,
      projectId: otherProject.id,
      name: "Sprint 1",
      targetDate: null,
    });
    await expect(
      milestoneService.closeMilestone(actor, {
        orgId,
        milestoneId: alpha.id,
        moveOpenIssuesTo: foreign.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const seenClosed: unknown[] = [];
    const offClosed = subscribe("milestone.closed", (payload) => {
      seenClosed.push(payload);
    });

    const closed = await milestoneService.closeMilestone(actor, {
      orgId,
      milestoneId: alpha.id,
      moveOpenIssuesTo: null,
    });
    expect(seenClosed).toHaveLength(1);
    expect(closed.milestone.closedAt).not.toBeNull();
    expect(new Set(closed.movedIssueIds)).toEqual(
      new Set([openIssue.id, second.id, mine.id, loose.id]),
    );
    expect((await issueRepo.findIssueById(orgId, done.id))?.milestoneId).toBe(alpha.id);
    expect((await issueRepo.findIssueById(orgId, canceled.id))?.milestoneId).toBe(
      alpha.id,
    );
    expect((await issueRepo.findIssueById(orgId, archived.id))?.milestoneId).toBe(
      alpha.id,
    );
    expect((await issueRepo.findIssueById(orgId, openIssue.id))?.milestoneId).toBeNull();

    await expect(
      milestoneService.closeMilestone(actor, {
        orgId,
        milestoneId: alpha.id,
        moveOpenIssuesTo: null,
      }),
    ).rejects.toMatchObject({ reason: "closed" });

    const notes = await listNotifications(tenant.actors.owner, {
      orgId,
      recipientId: tenant.userIds.admin,
      unreadOnly: false,
