/**
 * Open milestones first, then closed. Within a group, earliest target date
 * first and undated milestones last; equal dates keep the older milestone.
 */
function compareMilestones(a: Milestone, b: Milestone): number {
  const groupA = a.closedAt === null ? 0 : 1;
  const groupB = b.closedAt === null ? 0 : 1;
  if (groupA !== groupB) return groupA - groupB;

